sys_variable_value.value:
(function execute(inputs, outputs) {
    outputs.status_code = inputs.status_code;
    if (inputs.status_code != '201') {
        throw new Error('HTTP ' + inputs.status_code + ': ' + inputs.response_body);
    }
    var body = JSON.parse(inputs.response_body);
    outputs.remote_attachment_sys_id = body.result.sys_id;   // attachment sys_id on the partner
})(inputs, outputs);

